INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10, 'plPL', 'Skazani na Scrimshanka', 'Och, to po prostu straszne! Wysłałem mojego najlepszego asystenta, młodszego geodetę Scrimshanka, na pustynię na południowy wschód stąd. To teren, który nazywamy Ziejącą Rozpadliną. No i zaginął, a w ostatnim raporcie pisał, że tam, gdzie był, jest jeszcze więcej tych dziwnych robali. Czy to możliwe, że opanowały już dwa duże rejony pustyni?$B$BProszę, udaj się do Ziejącej Rozpadliny i poszukaj Scrimshanka! Albo... przynajmniej znajdź jego sprzęt mierniczy. Obawiam się, że tylko tyle mogło zostać po tym biedaku.', 'Ustal, co się stało z młodszym geodetą Scrimshankiem, i przyprowadź go albo przynieś jego sprzęt mierniczy starszemu geodecie Fizzledowserowi w Gadżetonie.', '', 'Wróć do starszego geodety Fizzledowsera w Gadżetonie w Tanaris.', '', '', '', '', 0),
(82, 'plPL', 'Śledztwo w Trującym Leżu', 'No dobrze, te raporty o robalach... wiemy tyle, że wysysają sadzawki z wodą, które kiedyś były tam, gdzie teraz jest Trujące Leże. Czego NIE wiemy? No cóż, całej reszty.$B$BNajpierw ustalmy, kim jest nasz wróg! Chcę, żebyś $gposzedł:poszła; do Trującego Leża i $gzdobył:zdobyła; trochę części tych stworzeń. Zbierz pięć od tamtejszych Centipaar i zanieś je alchemikowi Pestlezuggowi, niech się nimi pobawi. Gdy on się tym zajmie, na pewno ustalimy, co to za stwory!', 'Przynieś pięć części owadów Centipaar z Trującego Leża alchemikowi Pestlezuggowi w Gadżetonie.', '', 'Wróć do alchemika Pestlezugga w Gadżetonie w Tanaris.', '', '', '', '', 0),
(110, 'plPL', 'Analiza części owadów', 'Poświęcę trochę czasu na przejrzenie sprzętu mierniczego Scrimshanka... i na uporządkowanie jego rzeczy osobistych. Coś mnie swędzi za uszami, że to nie ostatnia strata, jaką poniesiemy przez te robale.$B$BChciałbym, żebyś $gzajrzał:zajrzała; do alchemika Pestlezugga i $gsprawdził:sprawdziła;, czy zdążył już zbadać części owadów, które mu wysłaliśmy. Jeśli wyniki są gotowe, przynieś mi je.', 'Odwiedź alchemika Pestlezugga w Gadżetonie i odbierz jego analizę części owadów.', '', '', '', '', '', '', 0),
(113, 'plPL', 'Analiza części owadów', 'Starszy geodeta Fizzledowser musi natychmiast zobaczyć ten raport. Właściwie... każdy, kto umie czytać, musi go zobaczyć. Stoimy przed poważnym zagrożeniem nie tylko dla Tanaris i Gadżetonu, ale – jeśli nic z tym nie zrobimy – dla całego południowego Kalimdoru. Do licha, może nawet dla całego Azeroth; nic nie wskazuje na to, żeby to miało ustać.$B$BNiech Fizzledowser zrobi dla ciebie kopię raportu, którą swobodnie przekażesz swoim sprzymierzeńcom. Wszyscy muszą wiedzieć o tym zagrożeniu!', 'Dostarcz raport starszemu geodecie Fizzledowserowi w Gadżetonie. Dopilnuj, żeby dał ci kopię raportu, tak jak prosił alchemik Pestlezugg.', '', '', '', '', '', '', 0),
(351, 'plPL', 'Odnajdź OOX-17/TN!', '$GOdkryłeś:Odkryłaś; jakieś dziwne metalowe urządzenie w kształcie jaja. Gdy majstrujesz przy jednym z pokręteł, jajo budzi się do życia i otwiera, zmieniając się w jakąś gnomią zrobotyzowaną maszynkę! Z wnętrza robotycznego jaja dobiega trzeszczący głos.$B$B„Nazywam się Oglethorpe i zaginął mój samonaprowadzający robot! Wynagrodzę cię za jego odnalezienie! Proszę, zanieś ten sygnalizator do robota. Świetnie, obliczyłem już dla ciebie współrzędne! Rozbił się w pobliżu Ziejącej Rozpadliny w Tanaris!”', 'Zanieś sygnalizator alarmowy do samonaprowadzającego robota Oglethorpe\'a.', '', '', '', '', '', '', 0),
(379, 'plPL', 'Ugaś to pragnienie', 'Chcesz źródło zasilania. Mogę ci w tym pomóc. Wiesz, czego ja chcę? Chcę się czegoś napić! Przynieś mi pięć bukłaków Pustynnych Tułaczy, a dam ci 4711-FTZ.$B$BA teraz... zgadnij, gdzie można znaleźć bukłaki Pustynnych Tułaczy! Może podejdziesz do któregoś z Pustynnych Tułaczy, którzy koczują na wschód stąd, i poprosisz o jeden? Daj znać, jak ci poszło.', 'Przynieś 5 bukłaków Pustynnych Tułaczy głównemu inżynierowi Zęzoświstowi w Gadżetonie.', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(654, 'plPL', 'Próbki terenowe z Tanaris', 'Po włączeniu źródła zasilania zestaw do testów terenowych zaczyna świecić i wibrować. Wygląda na to, że działa zgodnie z planem.$B$BZaraz zostanie wysłany.$B$BWedług głównego inżyniera Zęzośwista masz teraz trochę czasu na zebranie potrzebnych danych na pustyni Tanaris.$B$BGdy wykonasz zadanie, wróć do niego.', 'Zdobądź nieprzebadane próbki od 8 bazyliszków, 8 hien i 8 skorpiad. Odnieś zestaw testowy głównemu inżynierowi Zęzoświstowi w Gadżetonie, zanim wyczerpie się źródło zasilania.', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(841, 'plPL', 'Kolejne źródło zasilania?', 'Niech zgadnę – nie $gzdążyłeś:zdążyłaś; na czas z tym swoim niecnym, grożącym końcem świata przedsięwzięciem. Nie, czekaj, jeszcze lepiej... $gupuściłeś:upuściłaś; je w piasek! Cóż, bez względu na powód, mam jeszcze źródła zasilania, które mogę ci sprzedać. Tym razem jednak będzie cię to kosztować dziesięć, TAK, DZIESIĘĆ bukłaków Pustynnych Tułaczy!$B$BWszystkim teraz ciężko, $n, a źródła zasilania nie rosną na drzewach! Hmm, a gdyby rosły? Może dałoby się WYHODOWAĆ drzewo źródeł zasilania...', 'Przynieś 10 bukłaków Pustynnych Tułaczy głównemu inżynierowi Zęzoświstowi w Gadżetonie w zamian za kolejne źródło zasilania.', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(992, 'plPL', 'Badanie wód Gadżetonu', 'Mamy w Wodociągach Gadżetonu wolny etat tymczasowego młodszego geodety, jeśli cię to interesuje!$B$BSkoro koczownicy zajmują wszystkie nasze studnie, musimy korzystać z innych, wolnych źródeł wody! Na pustyni da się znaleźć wodę, ale tylko ci, którzy są na tyle sprytni, żeby najpierw ją zbadać.$B$BWeź ten gadżet różdżkarski i pobierz próbkę wody z sadzawki niedaleko Strażnicy Piaszczystego Smutku. Jest na widoku tamtejszych trolli. Gdy skończysz, przynieś mi zużyty gadżet!', 'Użyj nieużytego gadżetu różdżkarskiego przy sadzawce w pobliżu Strażnicy Piaszczystego Smutku. Gdy pobierzesz próbkę, zanieś zużyty gadżet różdżkarski starszemu geodecie Fizzledowserowi w Gadżetonie.', '', 'Wróć do starszego geodety Fizzledowsera w Gadżetonie w Tanaris.', '', '', '', '', 0),
(1157, 'plPL', '<NYI> <TXT> Pestlezugg potrzebuje przedmiotów', '', '', '', '', '', '', '', '', 0),
(1158, 'plPL', '<NYI> <TXT> Rozmowa z Rabine\'em Saturną', '', '', '', '', '', '', '', '', 0),
(1560, 'plPL', 'Zadanie Toogi', 'Ale się zgubiłem!$b$bMoja żona, Torta, wysłała mnie po kolację i gdzieś musiałem źle skręcić.$b$bCzy $gbyłbyś:byłabyś; tak $guprzejmy:uprzejma; i $gzaprowadził:zaprowadziła; mnie z powrotem do Torty? Czeka na mnie tuż na południe od Portu Parochlebców.', 'Odprowadź Toogę z powrotem do jego żony, Torty.', 'Zaprowadź Toogę do Torty', 'Wróć do Torty w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(1690, 'plPL', 'Sprawiedliwość dla Pustynnych Tułaczy', 'Hej, ty! Czas, żebyś porządnie $gprzysłużył:przysłużyła; się Wodociągom Gadżetonu.$B$BPustynni Tułacze, koczownicy z pustyni Tanaris, zajęli niemal wszystkie studnie! Bez dostępu do nich nasze zapasy wody wyschną w mgnieniu oka. Jeśli chcesz zyskać naszą przychylność, pomożesz nam wymierzyć tym koczownikom sprawiedliwość!$B$BRuszaj na wschód stąd i powal dziesięciu bandytów i złodziei Pustynnych Tułaczy, a potem biegiem wracaj do mnie z raportem. Sprawiedliwość nie czeka na żadnego człowieka... goblina... ech, po prostu bierz się do roboty!', 'Zabij 10 bandytów i złodziei Pustynnych Tułaczy na wschód od Gadżetonu, a następnie złóż raport głównemu inżynierowi Zęzoświstowi.', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(1691, 'plPL', 'Więcej sprawiedliwości dla Pustynnych Tułaczy', 'Teraz musisz się zmierzyć z silniejszymi Pustynnymi Tułaczami. Jak dotąd dobrze ci idzie, ale jeśli mamy odbić te studnie, to rozsądnie jest mieć przeciwko sobie jak najmniej koczowników!$B$BTym razem musisz zabić ich łotrów, zabójców i magów cienia. Znajdziesz ich na wschód i południowy wschód stąd.$B$BNie będę cię okłamywał – to paskudna banda. Ale zrób to dla nas, a będziemy na dobrej drodze, by odzyskać to, co nam się prawnie należy!', 'Zabij 10 magów cienia Pustynnych Tułaczy, 8 łotrów Pustynnych Tułaczy i 6 zabójców Pustynnych Tułaczy dla głównego inżyniera Zęzośwista w Gadżetonie.$B', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(1707, 'plPL', 'Nagroda za bukłaki', 'Witaj, $n – nazywam się Luglunket i mamy dla ciebie ważną robotę, jeśli masz ochotę! Hura!$B$BJako doświadczony operator kranu z największą przyjemnością przyjmę wszelkie bukłaki Pustynnych Tułaczy, jakie znajdziesz na pustyni. To i tak nasza woda – koczownicy po prostu ją ukradli i tyle! Za każde pięć, które oddasz, Wodociągi Gadżetonu dadzą ci oficjalną paczkę. A co najważniejsze, pomagasz Gadżetonowi pomóc samemu sobie!', 'Przynieś 5 bukłaków Pustynnych Tułaczy operatorowi kranu Luglunketowi w Gadżetonie.', '', 'Wróć do operatora kranu Luglunketa w Gadżetonie w Tanaris.', '', '', '', '', 0),
(1878, 'plPL', 'Nagroda za bukłaki', '', '', '', 'Wróć do operatora kranu Luglunketa w Tanaris.', '', '', '', '', 0),
(2605, 'plPL', 'Spragniony goblin', 'Mam pomysł, rozumiesz. Słyszałem o dziwnych stworzeniach zwanych zbieraczami rosy, które żyją na południowy zachód stąd... i że potrafią gromadzić wodę w specjalnych gruczołach.$B$BMyślę, że gdybym zdobył jeden z tych gruczołów, mógłbym stworzyć napój, który ugasi moje straszne pragnienie! Myślisz, że $gmógłbyś:mogłabyś; mi pomóc, $N?$B$BSzukaj ogrodu kaktusów, $N; tam znajdziesz zbieraczy rosy.', 'Zdobądź pełny gruczoł rosy i zanieś go Marinowi Noggenfoggerowi w Gadżetonie.', '', 'Wróć do Marina Noggenfoggera w Gadżetonie w Tanaris.', '', '', '', '', 0),
(2606, 'plPL', 'Kwestia smaku', 'Fuj! To paskudztwo smakuje okropnie! Tyle z tego pomysłu...$B$BChwila, co? Aha, wiem, wiem, uważasz, że nie powinienem się poddawać. No dobrze.$B$BEeee, mam pomysł! Genialny! Zanieś tę rosę mojej przyjaciółce Sprinkle – to świetna kucharka. Powiedz jej, co kombinujemy i że chcemy, żeby to łatwiej przechodziło przez gardło.$B$BTo znaczy, skoro ma tak paskudnie smakować, to niech przynajmniej ma trochę kopa... A ja go po prostu nie czuję...', 'Marin Noggenfogger chce, żebyś $gporozmawiał:porozmawiała; ze Sprinkle w Gadżetonie.', '', '', '', '', '', '', 0),
(2641, 'plPL', 'Sekretny składnik Sprinkle', 'Kiedy byłam mała, moja siostra zajmowała się całym gotowaniem. To było okropne! Ledwo mogłam przełknąć niektóre z jej mikstur – dopóki nie znalazłam czegoś, co lubię nazywać moim „sekretnym” składnikiem! Dodaj go do czegokolwiek i... O RANY! Smakuje wyśmienicie!$B$BCo to takiego, pytasz? To grzyb zwany fiołkowym traganem. Jeśli chcesz, żebym pomogła ci zmienić ten ohydny w smaku wywar w coś jadalnego, udaj się do Zaziemia i poszukaj tam małego jeziora.$B$BAch, i pamiętaj, fiołkowy tragan rośnie tylko pod wodą.', 'Sprinkle z Gadżetonu chce, żebyś $gzebrał:zebrała; fiołkowy tragan i $gprzyniósł:przyniosła; go jej.', '', 'Wróć do Sprinkle w Gadżetonie w Tanaris.', '', '', '', '', 0),
(2661, 'plPL', 'Przesyłka dla Marina', 'Oto fioletowy proszek, $N. Zanieś go Marinowi i powiedz mu, że wisi mi przysługę!', 'Sprinkle chce, żebyś $gzaniósł:zaniosła; fioletowy proszek Marinowi Noggenfoggerowi w Gadżetonie.', '', '', '', '', '', '', 0),
(2662, 'plPL', 'Eliksir Noggenfoggera', 'Teraz trzeba wmieszać ten proszek w rosę.$B$BWróć i porozmawiaj ze mną za minutkę... gdy już udoskonalę wspaniały Eliksir Noggenfoggera!', 'Marin Noggenfogger chce, żebyś znów z nim $gporozmawiał:porozmawiała;, gdy przyrządzi swój eliksir.', '', '', '', '', '', '', 0),
(2741, 'plPL', 'Super Jajomat', '', '', '', 'Wróć do Jajomatu w Tanaris.', '', '', '', '', 0),
(2747, 'plPL', 'Niezwykłe jajo', '', '', '', 'Wróć do Curgle Cranklehop w Tanaris.', '', '', '', '', 0),
(2748, 'plPL', 'Dobre jajo', '', '', '', 'Wróć do Curgle Cranklehop w Tanaris.', '', '', '', '', 0),
(2749, 'plPL', 'Zwyczajne jajo', '', '', '', 'Wróć do Curgle Cranklehop w Tanaris.', '', '', '', '', 0),
(2750, 'plPL', 'Zepsute jajo', '', '', '', 'Wróć do Curgle Cranklehop w Tanaris.', '', '', '', '', 0),
(2768, 'plPL', 'Różdżkomat', 'Sierżant Bly mnie okradł! Powiedział, że tylko pożyczy, ale ukradł mój ukochany różdżkomat!! Jak bez niego mam wiedzieć, gdzie kopać nowe wodopoje??$B$BZnajdź Bly\'a i przynieś mi mój różdżkomat! Słyszałem, że zabrał swoją bandę poszukiwaczy przygód o złej sławie na poszukiwanie skarbów do Zul\'Farrak, na zachodzie. Założę się, że tam go znajdziesz.$B$BMiejmy nadzieję, że trolle się nim zajęły, bo jeśli będziesz $gmusiał:musiała; walczyć z nim o różdżkomat, czeka cię ciężka przeprawa.', 'Przynieś różdżkomat głównemu inżynierowi Zęzoświstowi w Gadżetonie.', '', 'Wróć do głównego inżyniera Zęzośwista w Tanaris.', '', '', '', '', 0),
(2771, 'plPL', 'Głowa na karku', 'Wygląda na to, że mistrz od początku to zaplanował. Mnie nie nauczono wytwarzać przedmiotów, które ty $gpoznałeś:poznałaś;, a ciebie nie nauczono tych, które poznałem ja.$B$BMistrz jest mądry, $N. Nauczymy siebie nawzajem!$B$BPokaż mi, jak zrobić mithrilowy czepiec i zdobione mithrilowe naramienniki, a ja pokażę ci, jak wykuć zdobiony mithrilowy hełm.', 'Przynieś dwa mithrilowe czepce i jedne zdobione mithrilowe naramienniki Trentonowi Światłomłotowi.', '', 'Wróć do Trentona Światłomłota w Tanaris.', '', '', '', '', 0),
(2772, 'plPL', 'Świat u twoich stóp', 'Na zeszłorocznych Mistrzostwach Kowalskich Całej Doliny wszyscy widzowie widzieli, jak tchórzliwy pies z Odlewni spółki Gitgeszeft podciął mi nogę. Nie wiedzieli jednak, dzięki czemu mogłem walczyć dalej i ostatecznie wygrać turniej: tak jest, dzięki zdobionym mithrilowym butom!$B$BNa tegoroczny turniej muszę się jednak nauczyć wytwarzać zdobione mithrilowe spodnie, bo startuje w nim rozdrabniacz spółki Gitgeszeft! Naucz mnie drogi spodni, a poznasz drogę buta!', 'Przynieś dwie pary ciężkich mithrilowych butów i jedne zdobione mithrilowe spodnie Trentonowi Światłomłotowi.$B', '', 'Wróć do Trentona Światłomłota w Tanaris.', '', '', '', '', 0),
(2773, 'plPL', 'Mithrilowy Kid', 'W tych stronach jestem znany jako Mithrilowy Kid. Dostarczam zdobiony mithril poszukiwaczom przygód z całego świata.$B$B<Trenton szepcze.>$B$BMało kto wie, że nie znam techniki wytwarzania zdobionych mithrilowych rękawic. Ciii! To będzie nasza mała tajemnica.$B$BNaucz mnie techniki wytwarzania zdobionych mithrilowych rękawic, $N, a w zamian pokażę ci ukoronowanie mojej nauki u Galvana: zdobiony mithrilowy napierśnik.', 'Przynieś dwa ciężkie mithrilowe napierśniki i jedne zdobione mithrilowe rękawice Trentonowi Światłomłotowi.', '', 'Wróć do Trentona Światłomłota w Tanaris.', '', '', '', '', 0),
(2781, 'plPL', 'POSZUKIWANY: Kalif Skorpiożądło', 'POSZUKIWANY: Kalif Skorpiożądło!$B$BWodociągi Gadżetonu z Gadżetonu w Tanaris wypłacą wysoką nagrodę za głowę kalifa Skorpiożądła, przywódcy wyjętych spod prawa Pustynnych Tułaczy. Jego zbrodnie to między innymi:$B$B1. Mordowanie pracowników Wodociągów Gadżetonu!$B2. Kradzież zasobów Wodociągów Gadżetonu!$B3. Zajmowanie mienia Wodociągów Gadżetonu!$B$BDostarcz dowód śmierci kalifa Skorpiożądła głównemu inżynierowi Zęzoświstowi, by otrzymać natychmiastową nagrodę!', 'Przynieś głowę kalifa Skorpiożądła głównemu inżynierowi Zęzoświstowi w Gadżetonie.', '', 'Wróć do głównego inżyniera Zęzośwista w Gadżetonie w Tanaris.', '', '', '', '', 0),
(2865, 'plPL', 'Skorupy skarabeuszy', 'Skarabeusze z Tanaris mają bardzo twarde skorupy! Na tyle twarde, że nadają się na materiał budowlany do wielu rzeczy. Mnóstwa rzeczy!$B$BPrawdę mówiąc, te skorupy są tak przydatne... że skarabeusze wybito prawie do nogi!$B$BWiem, gdzie są jeszcze skarabeusze, i jeśli obiecasz, że przyniesiesz mi ich skorupy, powiem ci, gdzie ich szukać. Obiecujesz?$B$BDobra, skarabeusze mają kolonię w Zul\'Farrak. Chyba trolle nie polują na nie dla skorup.$B$BAle ty możesz! Idź do Zul\'Farrak i przynieś mi nienaruszone skorupy!', 'Przynieś 5 nienaruszonych skorup skarabeuszy Tran\'rekowi w Gadżetonie.', '', 'Wróć do Tran\'reka w Tanaris.', '', '', '', '', 0),
(2873, 'plPL', 'Przesyłka Stoleya', 'Jestem winien „Wilkowi Morskiemu” MacKinleyowi z Łupieżczej Zatoki trochę rumu, żeby rozliczyć zakład, ale skończył mi się rum! Kapitan Cuergo ukradł moją ostatnią dostawę i trzyma ją w tym otoczonym murem pirackim mieście na południu.$B$BJeśli znajdziesz moją dostawę rumu i mi ją zwrócisz, udowodnię MacKinleyowi, że gorzała z Kalimdoru bije na głowę tę z Łupieżczej Zatoki!', 'Przynieś przesyłkę Stoleya Stoleyowi w Porcie Parochlebców.', '', 'Wróć do Stoleya na Południowych Morzach w Tanaris.', '', '', '', '', 0),
(2875, 'plPL', 'POSZUKIWANY: Andre Ognistobrody', 'Podły pirat Andre Ognistobrody jest poszukiwany za zbrodnie przeciwko Parochlebcom i Gadżetonowi.$B$BNa mocy dekretu rady zarządzającej każdy, kto to przeczyta, zostaje niniejszym upoważniony do użycia śmiercionośnej siły podczas ujęcia Andrego i jego wspólników.$B$BNa mocy dalszego dekretu, jeśli Andre w czasie rozprawy będzie martwy lub w inny sposób niedysponowany, jego głowa może wystąpić jako pełnomocnik, a dostarczenie rzeczonej głowy szefowi ochrony Zęzoświstowi stanowi wiążącą i wymagalną umowę.', 'Przynieś głowę Andrego szefowi ochrony Zęzoświstowi w Porcie Parochlebców.', '', 'Wróć do szefa ochrony Zęzośwista w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(2876, 'plPL', 'Rozkłady rejsów', 'Ten zwój zawiera rozkłady transportów między Portem Parochlebców a Łupieżczą Zatoką. Są tu zarówno przeszłe, jak i przyszłe rejsy wraz z nazwami statków; przy niektórych rejsach widnieją duże „X”, a przy innych dopiski w rodzaju „ŚWIETNE ŁUPY” i „CIĘŻKA WALKA”.$B$BKtoś w Porcie Parochlebców na pewno chciałby zobaczyć ten dokument.', 'Zanieś rozkład rejsów przedstawicielowi władz w Porcie Parochlebców.', '', '', '', '', '', '', 0),
(2954, 'plPL', 'Kamienny Obserwator', '„Pozdrowienia – jestem strażnikiem wejścia. Jeśli nie masz Płyt Uldum już zintegrowanych z twoim zestawem dysków, nie zezwolę na wejście do kompleksu Uldum.”$B$BPojawienie się Kamiennego Obserwatora Norgannona musi być reakcją, na którą liczono, wysyłając cię z platynowymi dyskami na pustynię Tanaris. Zgodnie z poleceniem musisz się dowiedzieć, jaka historia kryje się za Kamiennym Obserwatorem, zanim ruszysz dalej.', 'Poznaj przeznaczenie Kamiennego Obserwatora Norgannona, a następnie użyj Piedestału Uldum na pustyni Tanaris.', 'Poznaj przeznaczenie Kamiennego Obserwatora Norgannona', 'Użyj Piedestału Uldum w Tanaris.', '', '', '', '', 0),
(2991, 'plPL', 'Medalion Nekruma', 'Dowiem się, gdzie jest twój gryf, ale najpierw musisz coś dla mnie zrobić. Nekrum Flakożuj, troll z Zul\'Farrak, ma medalion, który bardzo chciałbym zbadać. Przynieś mi ten medalion, a użyję swoich mocy, by odnaleźć Ostrodziobą.$B$BZul\'Farrak leży za oceanem na zachodzie, na pustyni Tanaris.', 'Przynieś medalion Nekruma Thadiusowi Ponuremu Cieniowi na Jałowych Ziemiach.', '', 'Wróć do Thadiusa Ponurego Cienia w Strażnicy Otchłani na Jałowych Ziemiach.', '', '', '', '', 0),
(3042, 'plPL', 'Trollowy środek hartujący', 'Trolle Piaskowej Furii z Zul\'Farrak wytwarzają z piaskowca środek hartujący, a ja mogę go użyć do hartowania wyrobów, które wykuwam, o tak! Koneserzy bardzo go cenią, więc jeśli przyniesiesz mi porządny zapas, sowicie cię wynagrodzę.$B$BZul\'Farrak leży na północny zachód od Gadżetonu. Powodzenia.', 'Przynieś 20 fiolek trollowego środka hartującego Trentonowi Światłomłotowi w Gadżetonie.', '', 'Wróć do Trentona Światłomłota w Tanaris.', '', '', '', '', 0),
(3064, 'plPL', '<NYI> <TXT> Pirackie kapelusze', 'Potrzebuję pirackich kapeluszy do mojego sklepu. Przynieś mi ich dużo!', 'Przynieś 20 nierozdartych pirackich kapeluszy Yorbie Śrubokran.', '', '', '', '', '', '', 0),
(3161, 'plPL', 'Gahz\'ridian', '$N, jestem naukowcem, ale w głębi serca także poszukiwaczem skarbów!$B$BDawno temu, gdy te ziemie zamieszkiwały trolle, wykonały one mnóstwo ozdób na wzór Gahz\'rilli, hydry, którą czciły jako bóstwo. Ozdoby te wyrzeźbiono z pierwiastka, który na cześć boga-hydry nazywam „Gahz\'ridian”.$B$BSam trochę go znalazłem, ale chciałbym mieć go więcej do badań – może ty coś znajdziesz?$B$BWynalazłem nawet wykrywacz, dzięki któremu znajdowanie Gahz\'ridian to pestka! Wystarczy go założyć i poszukiwania się zaczynają!', 'Marvon Nitoszukacz z Tanaris chce, żebyś $gzebrał:zebrała; 30 ozdób z Gahz\'ridian.', '', 'Wróć do Marvona Nitoszukacza przy Złamanym Filarze w Tanaris.', '', '', '', '', 0),
(3321, 'plPL', 'Czy to twoja zguba?', 'Wiele $gzrobiłeś:zrobiłaś; dla Zakonu, $N. Samo poświęcenie potrzebne, by zajść tak daleko, zniechęciłoby każdego zwykłego śmiertelnika. Nie mam wątpliwości – ani ja, ani Galvan – że jesteś $gjednym:jedną; z nas.$B$BDlatego uważam, że zasługujesz na małą nagrodę. To nic takiego, zwykły drobiazg. Być może znasz jego właściwości, bo wydaje mi się, że to właśnie on przywiódł cię do nas.', 'Zaczekaj, aż Trenton skończy swoją pracę.', 'Przyglądaj się pracy Trentona', 'Wróć do Trentona Światłomłota w Tanaris.', '', '', '', '', 0),
(3362, 'plPL', 'Dolina Ostowych Krzewów', '$GWidziałeś:Widziałaś; kiedyś Dolinę Ostowych Krzewów? To bardzo niebezpieczne miejsce, $N.$B$BNie ufam tamtejszym dziwnym stworom ani przez chwilę! Sękate ostowe krzewy i ostowi kształtownicy korzeni, chyba tak się nazywały...$B$BW każdym razie chcę się dostać do doliny, ale przy takiej liczbie tych ostowych krzewów w życiu tam nie wrócę. I tu wkraczasz ty – jeśli trochę ich wytępisz, może pomyślę o powrocie. Co ty na to, $N? Pomożesz mi?', 'Tran\'rek z Gadżetonu chce, żebyś $gzabił:zabiła; 8 sękatych ostowych krzewów i 8 ostowych kształtowników korzeni.', '', 'Wróć do Tran\'reka w Tanaris.', '', '', '', '', 0),
(3402, 'plPL', 'Podziemny Targ', 'Chcę, żebyś osobiście $gprzekazał:przekazała; Vizzklickowi w Gadżetonie wieść o pokonaniu Kovica. Tak się ucieszy, słysząc, że Kovic nie żyje, że na pewno da ci jakąś wspaniałą nagrodę.', 'Porozmawiaj z Vizzklickiem w Gadżetonie.$B', '', '', '', '', '', '', 0),
(3444, 'plPL', 'Kamienny krąg', 'Kiedyś wszedłem do złowieszczych komnat Zatopionej Świątyni. Zło tego miejsca przenika każdego, kto tam wejdzie; ledwie udało mi się wydostać, brnąc przez szlam, który teraz pokrywa posadzki. Pamiętam tylko, że zataczając się, przechodziłem przez dużą okrągłą salę pełną posągów węży...$B$BNiedawno odkryłem okrągły kamień, na którym wyryto chyba ten sam symbol węża. Kazałem go zapakować i wysłać do mojego warsztatu w Zapadce. Przynieś go, a może będę mógł powiedzieć ci więcej.', 'Odbierz kamienny krąg z warsztatu Marvona Nitoszukacza w Zapadce.', '', 'Wróć do Marvona Nitoszukacza przy Złamanym Filarze w Tanaris.', '', '', '', '', 0),
(3446, 'plPL', 'W głąb', 'W świątyni znalazłem okrągłą salę z sześcioma balkonami, a na krawędzi każdego z nich stał posąg węża. Z ciekawości pchnąłem jeden z nich, żeby zobaczyć, co się stanie – i to była pułapka! Omal nie zginąłem od wybuchu. Leżąc na półce, spojrzałem w dół i zauważyłem kolejny posąg u podstawy sali; coś w rodzaju ołtarza... Hakkara, jeśli dobrze pamiętam.$B$BMyślę, że w tym ołtarzu tkwi sekret – musisz zanieść ten żeton do ołtarza w Zatopionej Świątyni.', 'Odnajdź Ołtarz Hakkara w Zatopionej Świątyni na Moczarach Smutków.', '', '', '', '', '', '', 0),
(3447, 'plPL', 'Sekret kręgu', 'Wspomnienia mam mgliste, ale powiem ci, co mogę. Krąg posągów w Zatopionej Świątyni jest niebezpieczny, ale sądzę, że kryje sekret, który pozwoli dotrzeć do jeszcze większego skarbu.$B$BZ głównego ołtarza udało mi się uruchomić serię świateł. Myślę, że jeśli odkryjesz, co oznaczają, może zdołasz odsłonić sekrety ukryte w tej sali.$B$BOstrzegam cię jednak, $N. W świątyni czai się wielkie zło. Wszystko, co cenne, jest zapewne zaciekle strzeżone...', 'Udaj się do Zatopionej Świątyni i odkryj sekret ukryty w kręgu posągów.', '', '', '', '', '', '', 0),
(3520, 'plPL', 'Duchy skrzekunów', 'Szukam duchów skrzekunów z doliny w Feralas. To kuzyni starego, prastarego boga, a ich duchy są z nim związane.$B$BWeź tę różdżkę z cierniokrzewu i udaj się do Feralas. Odszukaj i pokonaj skrzekuny z doliny w południowym i środkowym Feralas, a potem machnij moim cierniokrzewem nad ich martwymi ciałami. To skłoni ich ducha, by się ujawnił. Dotknij ducha i zbierz jego esencję.$B$BWróć do mnie z moim cierniokrzewem i zebraną esencją, a powiem ci więcej o starym bogu, o którym wspomniałem.', 'Schwytaj duchy 3 skrzekunów w Feralas, a następnie wróć do Yeh\'kinyi w Porcie Parochlebców.', '', 'Wróć do Yeh\'kinyi w Porcie Parochlebców w Tanaris.', 'Zebrane duchy skrzekunów', '', '', '', 0),
(3527, 'plPL', 'Proroctwo Mosh\'aru', 'Starożytne proroctwo Mosh\'aru mówi o sposobie na uwięzienie esencji boga Hakkara. Spisano je na dwóch tablicach i zabrano do trollowego miasta Zul\'Farrak, na zachód od Gadżetonu.$B$BPrzynieś mi tablice Mosh\'aru!$B$BPierwszą tablicę ma dawno zmarły troll Theka Męczennik. Podobno jego prześladowców dosięgła klątwa, która zamieniła ich w skarabeusze, i teraz pełzają wokół jego kapliczki.$B$BDrugą tablicę ma hydromantka Velratha, przy świętej sadzawce Gahz\'rilli.$B$BGdy zdobędziesz tablice, przynieś mi je.', 'Przynieś pierwszą i drugą tablicę Mosh\'aru Yeh\'kinyi w Tanaris.', '', 'Wróć do Yeh\'kinyi w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(3528, 'plPL', 'Bóg Hakkar', 'Nadszedł czas, by schwytać esencję awatara Hakkara.$B$BZanieś jajo Hakkara do Sanktuarium Upadłego Boga w Zatopionej Świątyni w Azeroth. Przywołaj moc jaja, by poruszyć martwego boga.$B$BHakkar wyśle przeciwko tobie swoje sługi. Pokonaj jego krwiopijców i zabierz im krew Hakkari, a potem użyj jej, by ugasić wieczne płomienie, które więżą ducha Hakkara. Gdy zgasną wszystkie płomienie, awatar Hakkara wkroczy do naszego świata.$B$BPokonaj go i umieść jego esencję w jaju Hakkara.', 'Przynieś napełnione jajo Hakkara Yeh\'kinyi w Tanaris.', '', 'Wróć do Yeh\'kinyi w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(3638, 'plPL', 'Przyrzeczenie tajemnicy', 'W goblińskiej inżynierii chodzi o praktyczne zastosowania, wysoki zysk i jeszcze wyższą siłę wybuchu! Nasze schematy pozwalają budować potężne bomby i groźną broń; była o tym mowa w podręczniku, który $gprzeczytałeś:przeczytałaś;.$B$BW podręczniku była też mowa o naszej odwiecznej przysiędze, że schematy pozostaną tajemnicą. Gdy zostaniesz $ginżynierem goblińskim:inżynierką goblińską;, klamka zapadła. Do gnomiej inżynierii nie będziesz mieć żadnego dostępu.$B$BJeśli nadal chcesz zostać $ginżynierem goblińskim:inżynierką goblińską;, podpisz ten dokument, przyrzekając dożywotnie zachowanie tajemnicy, i porozmawiaj ze mną ponownie. Dobrze się zastanów, $N.', 'Jeśli zgadzasz się zostać $ginżynierem goblińskim:inżynierką goblińską;, kliknij prawym przyciskiem Przyrzeczenie tajemnicy i porozmawiaj jeszcze raz z Nixxem Sprężynotrybem w Gadżetonie.', '', 'Wróć do Nixxa Sprężynotryba w Tanaris.', '', '', '', '', 0),
(3885, 'plPL', '<NYI> <TXT> Bieg do Gadżetonu', 'Eskortuj mnie i Dadangę!', 'Eskortuj Petrę i Dadangę!', 'Odeskortuj Petrę i Dadangę!', 'Wróć do Petry Grossen.', '', '', '', '', 0),
(3910, 'plPL', '<NYI> <TXT> Bieg przez Un\'Goro', 'Witamy w Gadżetonie! Zabierz nas do domu...', 'Odeskortuj Petrę i Dadangę z powrotem do Un\'Goro.', 'Odeskortuj Petrę i Dadangę!', 'Wróć do Petry Grossen.', '', '', '', '', 0),
(3912, 'plPL', 'Spotkanie przy grobie', 'Ten eliksir pozwoli ci porozmawiać z kimś, kogo normalnie nawet byś nie $gzobaczył:zobaczyła;...$B$BZabierz eliksir Videre razem z mieczem Linkena na cmentarz tuż za Gadżetonem w Tanaris. Na miejscu wypij miksturę. Efekt może cię mocno zaskoczyć, ale nie daj się przestraszyć.$B$BW tej „innej” postaci idź prosto na północ, aż dotrzesz do gór. Ten, z kim musisz porozmawiać, czeka w jednej ze skalnych szczelin. Ma na imię Gaeriyan.$B$BPamiętaj, porozmawia z tobą tylko wtedy, gdy będziesz w tej postaci...', 'Udaj się na cmentarz za Gadżetonem i użyj eliksiru Videre. Postępuj zgodnie z resztą wskazówek Donovy, by odnaleźć Gaeriyana.', '', '', '', '', '', '', 0),
(3913, 'plPL', 'Grobowa sytuacja', 'Jeśli wrócisz na cmentarz, $N, znajdziesz tam nagrobek... Nie byle jaki; ten będzie się wyróżniał spośród innych. Kryje w sobie tajemnice.$B$BPchnij kamień, a poznasz te tajemnice...', 'Wskrześ się, a potem odszukaj nagrobek, o którym mówił ci Gaeriyan.', '', '', '', '', '', '', 0),
(3914, 'plPL', 'Miecz Linkena', 'Po silnym błysku światła możesz znów podnieść miecz. Przeszedł przemianę!', 'Dostarcz znakomity miecz Linkena Linkenowi w Kraterze Un\'Goro.', '', '', '', '', '', '', 0),
(4324, 'plPL', 'Yuka Śrubokran', 'Mój młodszy brat Ribbly przez całe życie był nic niewart, ale chyba wreszcie na coś się przyda! Tyle że... możemy potrzebować twojej pomocy, żeby zarobić na tej jego nowo odkrytej wartości.$B$BMoja siostra Yuka szuka go od tygodni i wytropiła go na Płonących Stepach. Przysłała mi wiadomość z prośbą o parę rąk do pracy.$B$BNo to jak? Chcesz pomóc? Jeśli tak, porozmawiaj z moją siostrą. Ukrywa się na Płomiennym Grzbiecie, w jaskini na północny zachód od Skały Upiornych Maczug.', 'Porozmawiaj z Yuką Śrubokran na Płonących Stepach.', '', '', '', '', '', '', 0),
(4450, 'plPL', 'Księga rachunkowa z Tanaris', 'O, wiesz co? Coś mi się przypomniało.$B$BChcesz dokończyć za mnie drobne zlecenie z Tanaris? To łatwizna...$B$BKrinkle Dobrostal z Gadżetonu szukał paru rzeczy, które można znaleźć tu, w Płonącym Wąwozie, i w kilku innych miejscach. Może rzucisz okiem na listę i przyniesiesz mu to wszystko?$B$BJeśli jesteś $gzainteresowany:zainteresowana;, wsunę ci jego księgę rachunkową pod drzwiami. Weź ją, a jak już zbierzesz wszystko, czego chce, zanieś mu to razem z nią.', 'Weź kopię księgi rachunkowej Dobrostala, znajdź wymienione w niej przedmioty, a potem odszukaj Krinkle\'a Dobrostala w Tanaris.', '', 'Wróć do Krinkle\'a Dobrostala w Gadżetonie w Tanaris.', '', '', '', '', 0),
(4496, 'plPL', 'Wpadka w dżungli', 'Moje badania wykazały, że silithidy są jak pszczoły: zniszcz królową roju, a reszta powinna popaść w rozsypkę. Uwarzę przynętę, dzięki której wywabimy królową; gdy już się pojawi, ty ją zabijesz.$B$BNajpierw jednak potrzebujemy paru składników – nie chcemy, żebyś $gwpadł:wpadła; do dżungli $gnieprzygotowany:nieprzygotowana;. Idź na zachód, do roju silithidów w Kraterze Un\'Goro, i zdobądź gruczoł zapachowy jednego z tych robali. Potrzebuję też kilku próbek tamtejszej ziemi z Un\'Goro.', 'Przynieś gruczoł zapachowy Gorishi i 5 próbek ziemi z Un\'Goro alchemikowi Pestlezuggowi w Gadżetonie.', '', 'Wróć do alchemika Pestlezugga w Gadżetonie w Tanaris.', '', '', '', '', 0),
(4504, 'plPL', 'Superlepkie', 'Zawsze szukam szybkiego sposobu na zarobienie sztuki złota, $N. Jeśli pomożesz mi z moim najnowszym pomysłem, dam ci udział w zyskach. Co ty na to?$B$BTak myślałem!$B$BUdaj się do smolistych jam w północnej części Krateru Un\'Goro i zbierz dla mnie trochę smoły. Tylko nie byle jakiej! Musisz ją zdobyć od bestii, które żyją wokół smolistych jam. Zwykła smoła po prostu nie jest dość lepka.$B$BTe roślinopodobne stwory mają w skórze chlorofil, a zmieszany ze smołą daje coś superlepkiego!', 'Zbierz 12 próbek superlepkiej smoły dla Tran\'reka w Gadżetonie.', '', 'Wróć do Tran\'reka w Gadżetonie w Tanaris.', '', '', '', '', 0),
(4507, 'plPL', 'Pionek bije królową', 'Oto przynęta. Gdzieś w sieci tuneli roju powinien być jakiś kryształ. Sądzimy, że silithidy używają go jako czegoś w rodzaju urządzenia, które zestraja cały rój. Gdzie szukać tego kryształu? Spróbuj w wylęgarniach wewnątrz roju.$B$BUżycie przynęty na krysztale powinno wywabić królową, ale uważaj – najpewniej będzie jej strzec kilku strażników. Zabij królową i wyjmij jej mózg. Choć brzmi to obrzydliwie, bardzo potrzebujemy go do badań. Powodzenia, $N!', 'Pokonaj królową roju Gorishi, gdy już się pojawi.$B$BZanieś mózg królowej Gorishi alchemikowi Pestlezuggowi w Gadżetonie.', '', 'Wróć do alchemika Pestlezugga w Gadżetonie w Tanaris.', '', '', '', '', 0),
(4788, 'plPL', 'Ostatnie tablice', 'Kiedy ja będę badał trzecią i czwartą tablicę Mosh\'aru, ty musisz znaleźć piątą i szóstą! Nie będzie łatwo, bo mają je trolle z plemienia Tlącego Ciernia w Iglicy Czarnej Góry. Iglica to mroczna, ognista góra między Płonącymi Stepami a Płonącym Wąwozem.$B$BPowodzenia, $N. Iglica Czarnej Góry to nie miejsce dla porządnych ludzi...', 'Przynieś piątą i szóstą tablicę Mosh\'aru poszukiwaczowi Żelaznemu Butowi w Tanaris.', '', 'Wróć do poszukiwacza Żelaznego Buta na Południowych Morzach w Tanaris.', '', '', '', '', 0),
(5065, 'plPL', 'Zaginione tablice Mosh\'aru', 'Troll, z którym $grozmawiałeś:rozmawiałaś;, nie powiedział prawdy. Dwie tablice, które dla niego $gzdobyłeś:zdobyłaś;, mówiły o uwięzieniu esencji Hakkara, ale ta legenda ma drugie dno. Długo prowadziłem badania i odkryłem, że tablic Mosh\'aru jest sześć, a nie dwie! Sześć!$B$BI obawiam się, że tajemnice pozostałych nam się nie spodobają...$B$BZnajdź trzecią i czwartą tablicę Mosh\'aru. Są na Wschodnich Plagowiskach, w rękach trolli z plemienia Mchołupów. Znajdź je i przynieś mi.', 'Przynieś trzecią i czwartą tablicę Mosh\'aru poszukiwaczowi Żelaznemu Butowi w Tanaris.', '', 'Wróć do poszukiwacza Żelaznego Buta w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(5537, 'plPL', 'Fragmenty szkieletów', 'Klucz do Scholomancjum nazywa się wytrychem. Trzeba go wykuć ze szczątków szkieletu – a właściwie kilku – i zahartować w odpowiedniej formie tylko najtwardszymi z metali. Ostatecznie zadziała dopiero dzięki pieczęci mocy istoty, która z natury potrafi otworzyć portal do Scholomancjum.$B$BAle po kolei, $N. Do wykucia klucza potrzebujemy fragmentów szkieletów. Szkielety w Andorhalu powinny dać nam to, czego trzeba, ale te spod murów też mogą się nadać.', 'Przynieś 15 fragmentów szkieletów alchemikowi Arbingtonowi do Punktu Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do alchemika Arbingtona w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5538, 'plPL', 'Forma za forsę', 'Goblin, z którym musisz porozmawiać, to Krinkle Dobrostal. Sprzedaje swoje umiejętności temu, kto da najwięcej, w Gadżetonie na pustyni Tanaris. Najpewniej tylko on zdoła wykonać formę, której potrzebujemy, a jego usługi nie będą tanie. Teraz prosimy cię, żebyś $gsięgnął:sięgnęła; głęboko do sakiewki i pokrył opłatę, jakiej zażąda.$B$BJestem alchemikiem, nie bankierem. Gdybym miał złoto pod ręką, na pewno by mnie tu nie było.$B$BChyba znowu powiedziałem na głos to, co miało zostać w mojej głowie. Ups.$B$BGadżeton czeka! Powodzenia!', 'Zanieś nasycone fragmenty szkieletów i 15 sztuk złota Krinkle\'owi Dobrostalowi w Gadżetonie.', '', '', '', '', '', '', 0),
(5801, 'plPL', 'Wykuty w Grani Ognistej Smugi', 'Żeby wykuć trzon klucza, potrzebujesz dwóch sztabek torium i bardzo gorącego źródła ciepła. Torium musisz zdobyć $gsam:sama;, ale z ciepłem mogę pomóc.$B$BNa zachód od nas, w Kraterze Un\'Goro, leży Grań Ognistej Smugi – tlący się wulkan. Jezioro lawy na szczycie jest dość gorące, by stopić razem torium i kość. Za twoje złoto dostajesz formę, którą wystarczy zanurzyć w tym jeziorze; resztą zajmie się lawa.$B$BTo tyle z mojej strony. Żeby dokończyć klucz, musisz znów porozmawiać z Arbingtonem.', 'Zanieś formę na wytrych i 2 sztabki torium na szczyt Grani Ognistej Smugi w Kraterze Un\'Goro. Użyj formy na wytrych przy jeziorze lawy, by wykuć niedokończony wytrych.$B$BZanieś niedokończony wytrych alchemikowi Arbingtonowi w Punkcie Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do alchemika Arbingtona w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5803, 'plPL', 'Skarabeusz Araja', 'Araj Przywoływacz włada Andorhalem z serca zrujnowanego miasta. Wiemy, że zanim przywłaszczył sobie miasto, był przywódcą Scholomancjum. Aby dokończyć klucz, potrzebujemy jego sygnetu – zwanego skarabeuszem – osadzonego jako główka klucza.$B$BDotrzyj do serca Andorhalu i złam jego władzę nad miastem, teraz gdy wyszedł z ukrycia. Gdy go zniszczysz, zabierz skarabeusza z jego rozbitej filakterii!$B$BKlucz do Scholomancjum czeka, $N!', 'Zniszcz Araja Przywoływacza i przynieś skarabeusza Araja alchemikowi Arbingtonowi do Punktu Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do alchemika Arbingtona w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5863, 'plPL', 'Siedlisko Wydmowych Maczug', 'Niedawno do Tanaris przybyła duża banda koczowniczych ogrów. Na południe stąd zajęły spory kawał pustyni i założyły tam siedlisko. Kilka mniejszych band wędruje teraz po pustyni, a niektóre z nich wtargnęły do starych trollowych ruin.$B$BSiedlisko Wydmowych Maczug musi zostać zniszczone! Nie możemy pozwolić, żeby te ogry zebrały siły.$B$BPrzywódca tej bandy nazywa się Gor\'marok Pustoszyciel. Wierzę, że koniec jego rządów będzie początkiem końca ogrów.', 'Andi Lynn z Gadżetonu chce, żebyś $gzniszczył:zniszczyła; Siedlisko Wydmowych Maczug, zabijając 10 osiłków Wydmowych Maczug, 10 egzekutorów Wydmowych Maczug i Gor\'maroka Pustoszyciela.', '', 'Wróć do Andi Lynn w Tanaris.', '', '', '', '', 0),
(6610, 'plPL', 'Niespodzianka z małżami', '$GSłyszałeś:Słyszałaś; kiedyś o małżowym omlecie? Pewnie, że nie! To moje najnowsze i największe kulinarne arcydzieło. Och, $N, na samą myśl o małżowym omlecie cieknie mi ślinka.$B$BNiestety, skończyły mi się składniki! Może ubijemy interes? Ty zbierzesz to, czego potrzebuję do małżowego omletu, a ja nauczę cię tajników egzotycznej kuchni i jeszcze dorzucę parę omletów! Umowa??$B$BOto, czego potrzebuję:', 'Dirge Szybkosiek chce, żebyś $gzdobył:zdobyła; następujące przedmioty:$B$B10 olbrzymich jaj. Znajdziesz je u roków wędrujących po Tanaris albo u innych gatunków dużych ptaków.$B$B10 porcji ostrego mięsa małży. Znajdziesz je w małżach, rzecz jasna!$B$B20 porcji sera dziurawego z Alterak. Idźże do serowarni!$B$BZbierz wszystkie przedmioty i wróć do Dirge\'a.', '', 'Wróć do Dirge\'a Szybkosieka w Tanaris.', '', '', '', '', 0),
(7652, 'plPL', 'Okazja spod lady', '', '', '', '', '', '', '', '', 0),
