INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1551, 'plPL', 'Witajcie i bądźcie pozdrowieni, poszukiwacze przygód!\n\nJa, Krinkle Dobrostal, potrzebuję śmiałków gotowych zaryzykować, by wykonać kilka moich najbardziej żmudnych zadań. Mam mnóstwo obowiązków i tyle pracy, ile zdołałem sobie nabrać, więc gwarantuję, że każdy, kto odważy się zdobyć rzeczy z tej listy i dostarczyć mi je w nienaruszonym stanie, otrzyma sowitą zapłatę. \n\nLista znajduje się na kolejnych stronach...', 0),
(1552, 'plPL', 'Lite kryształowe trzony nóg – \n\nPająki szklanej sieci z Płonącego Wąwozu zbudowane są z niezwykłego, podobnego do kryształu materiału. Ich nogi, jeśli nie zostaną uszkodzone podczas zabijania pająka, są wspaniałym przewodnikiem w niektórych inżynieryjnych eksperymentach moich towarzyszy.\n\nPotrzebuję ich kilku do testów. Skoro każdy pająk ma aż osiem nóg, nie powinno to stanowić problemu dla dzielnego wojownika czy wprawnego maga.', 0),
(1553, 'plPL', 'Spóźniona paczka –\n\nWynająłem kogoś, kogo uważałem za solidnego pilota, żeby przywiózł mi paczkę z Theramore. Najwyraźniej się pomyliłem. I choć pilot przeżył i może o tym opowiadać, porzucił cały sterowiec razem z ładunkiem, żeby ratować własną skórę.\n\nCóż, chcę odzyskać tę paczkę. Z tego, co mówi Beezil, rozbił się tuż na zachód od zatoki na Pyłowym Bagnisku. Spadł zaraz po tym, jak przeleciał nad wzgórzami wzdłuż brzegu.\n\nHmmm... nigdy mi nie powiedział, dlaczego się rozbił... ', 0),
(1554, 'plPL', 'Wyważony flamberg Dobrostala – \n\nNa koniec chcę odzyskać jedno z moich najwspanialszych jak dotąd dzieł kowalskich. Ten flamberg był niesamowitym mieczem, który podarowałem komuś, kogo uważałem za bardzo honorowego i wielkiego wojownika. No cóż, sprał go murlok imieniem Jarquai? Jakoś tak. \n\nWędrował właśnie wybrzeżem Moczarów Smutków, gdy przyszło mu do głowy zaatakować stwora. Poniósł porażkę i najwyraźniej uciekł, ale wcześniej zostawił broń, którą ten murlok sobie zabrał.', 0),
(1556, 'plPL', 'Znajdź dla mnie te rzeczy i wróć z nimi wszystkimi do Gadżetonu, razem z tą księgą rachunkową, a wynagrodzę cię. ', 0),
(1590, 'plPL', 'Znajdź dla mnie te rzeczy i wróć z nimi wszystkimi do Gadżetonu, razem z tą księgą rachunkową, a wynagrodzę cię. ', 0),
(2104, 'plPL', 'Choć zwycięstwo należało do nich, śmiertelne rasy znalazły się w świecie zdruzgotanym przez wojnę. Plaga i Płonący Legion niemal całkowicie zniszczyły cywilizacje Lordaeronu i omal nie dokończyły dzieła w Kalimdorze. Trzeba było uzdrowić lasy, pogrzebać urazy i zasiedlić ojczyzny. Wojna głęboko zraniła każdą z ras, lecz bezinteresownie się zjednoczyły, by spróbować zacząć od nowa, poczynając od niepewnego rozejmu między Przymierzem a Hordą.', 0),
(2105, 'plPL', 'Thrall poprowadził orków na kontynent Kalimdor, gdzie z pomocą swoich braci taurenów założyli nową ojczyznę. Nazwali swoją nową ziemię Durotarem, na cześć zamordowanego ojca Thralla, i osiedlili się, by odbudować swoją niegdyś wspaniałą społeczność.', 0),
(2106, 'plPL', 'Teraz, gdy demoniczna klątwa dobiegła końca, Horda przestała być wojowniczą, niszczycielską potęgą i stała się raczej luźną koalicją, nastawioną na przetrwanie i dobrobyt, a nie na podboje. Wspierani przez szlachetnych taurenów i przebiegłe trolle z plemienia Mrocznej Włóczni, Thrall i jego orkowie wyczekiwali nowej ery pokoju na własnej ziemi.', 0),
(2107, 'plPL', 'Pozostałe siły Przymierza pod wodzą Jainy Proudmoore osiedliły się w południowym Kalimdorze. U wschodnich wybrzeży Pyłowego Bagniska zbudowały surowe miasto portowe Theramore. Tam ludzie i ich krasnoludzcy sojusznicy walczyli o przetrwanie w krainie, która zawsze miała być im wroga. Choć obrońcy Durotaru i Theramore przestrzegali wzajemnie kruchego rozejmu, delikatnemu spokojowi kolonii nie było dane przetrwać.', 0),
(2108, 'plPL', 'Pokój między orkami a ludźmi legł w gruzach, gdy do Kalimdoru przybyła ogromna flota Przymierza. Potężna flota pod dowództwem wielkiego admirała Daelina Proudmoore\'a (ojca Jainy)\n opuściła Lordaeron, zanim Arthas zniszczył królestwo. Po wielu wyczerpujących miesiącach żeglugi admirał Proudmoore szukał wszystkich ocalałych z Przymierza, jakich zdołałby znaleźć.', 0),
(2109, 'plPL', 'Armada Proudmoore\'a stanowiła poważne zagrożenie dla stabilności regionu. Ojciec Jainy, słynny bohater Drugiej Wojny, był zagorzałym wrogiem Hordy i postanowił zniszczyć Durotar, zanim orkowie zdążą zapuścić korzenie na tej ziemi.', 0),
(2110, 'plPL', 'Wielki admirał zmusił Jainę do strasznego wyboru: wesprzeć go w walce z orkami i zdradzić nowych sojuszników albo walczyć z własnym ojcem, by zachować kruchy pokój, który Przymierze i Horda wreszcie osiągnęły. Po długich rozterkach Jaina wybrała to drugie i pomogła Thrallowi pokonać swojego obłąkanego ojca. ', 0),
(2111, 'plPL', 'Niestety admirał Proudmoore zginął w bitwie, zanim Jaina zdążyła się z nim pojednać lub udowodnić mu, że orkowie nie są już żądnymi krwi potworami. W nagrodę za jej lojalność orkowie pozwolili siłom Jainy bezpiecznie wrócić do domu, do Theramore.', 0),
(2793, 'plPL', 'Minęło niemal tysiąc lat od „Wojny Ruchomych Piasków”. To właśnie podczas tej wojny, w sercu pustyni Silithus, Fandrala Jeleniorogiego spotkała wielka tragedia i jeszcze większe brzemię. Uważa się, że opisane tu wydarzenia ostatecznie ukształtowały niemiłe usposobienie arcydruida.', 0),
(2794, 'plPL', 'Pradawna rozumna rasa owadopodobnych istot zwanych Qiraji walczyła niegdyś o panowanie nad znaczną częścią Kalimdoru. To napuszony, imperialistyczny Jeleniorogi i jego armia nocnych elfów stawili czoła Qiraji w otwartej bitwie.$B', 0),
(2795, 'plPL', 'Ojciec i syn walczyli zażarcie, by powstrzymać wzbierającą falę owadziego roju w Silithusie. Z twierdzy Ahn\'Qiraj płynął pozornie nieskończony strumień silithidów, który wciąż zasilał szeregi najeźdźczych sił Qiraji. Cały Silithus znalazł się w oblężeniu.$B', 0),
(2796, 'plPL', 'Jeleniorogi wydał rozkaz, którego miał potem żałować: jego syn Valstann miał bronić placówki nocnych elfów w Osadzie Południowego Wiatru. Niestety Valstann stracił tego dnia życie, gdy Osada Południowego Wiatru padła pod naporem armii Ahn\'Qiraj.$B', 0),
(2797, 'plPL', 'Nieustraszony, choć z ciężkim sercem, żądny zemsty Fandral Jeleniorogi parł naprzód. Klęska w Silithusie oznaczałaby wielką stratę dla narodu nocnych elfów, a być może i dla całego świata.$B$BBitwa trwała miesiącami. Qiraji opanowali cały Silithus. Jeleniorogi i jego armia zostali zepchnięci do Tanaris. Gdy armia była zdziesiątkowana, a niezliczeni niewinni polegli, arogancja, która napędzała Fandrala Jeleniorogiego, zgasła całkowicie.', 0),
(2798, 'plPL', 'Jego duma została doszczętnie zdruzgotana. Jeleniorogi po raz drugi w życiu poczuł w dołku to drżenie, które może wywołać tylko strach. I to właśnie w Tanaris Jeleniorogi zwrócił się do Anachronosa, potomka Nozdormu, błagając o pomoc Brązowego Stada.', 0),
(2799, 'plPL', 'Początkowo Anachronos odmówił wciągania Brązowego Stada w sprawy pośledniejszych ras. Dopiero gdy Qiraji zuchwale zaatakowali Jaskinie Czasu, Anachronos zgodził się połączyć siły z nocnymi elfami.', 0),
(2800, 'plPL', 'Anachronos wkrótce zrozumiał, że nawet potężne Brązowe Stado nie zdoła powstrzymać fali najeźdźczych sił Qiraji. Na każde pięćdziesiąt owadów unicestwionych jego oddechem czekała setka gotowych zająć ich miejsce. Gdy szeregi nocnych elfów słabły, a nad nimi wisiała groźba zepchnięcia dalej na północ, w dzicz Feralas, Anachronos uznał, że trzeba zawiadomić dzieci Aspektów.', 0),
(2801, 'plPL', 'Najpierw wezwał stado Ysery. Na jego wezwanie odpowiedziała Merithra ze Snu, a potem wieść dotarła do stada Alexstrazy i stada Malygosa.', 0),
(2802, 'plPL', 'Smoki spotkały się w stratosferze wysoko nad Silithusem: tysiące stóp nad twierdzą Ahn\'Qiraj.$B$BByli tam: Anachronos, dziecko Nozdormu, Aspektu Czasu. $B$BZe Szmaragdowego Snu przybyła Merithra, dziecko Ysery, Aspektu Natury.$B$BCaelestrasz, dziecko Alexstrazy, Aspektu Życia, reprezentował Czerwone Stado.$B$BArygos, dziecko Malygosa, Aspektu Magii, reprezentował Błękitne Stado.$B', 0),
(2803, 'plPL', 'Smoki patrzyły, jak z Ahn\'Qiraj wylewa się nieskończony strumień silithidów i Qiraji. Stało się dla nich jasne, że żadna siła nie zdoła zakończyć tej wojny. W głównej świątyni czekały dziesiątki tysięcy wojowników Qiraji. Z każdą sekundą wykluwali się i szykowali kolejni, gotowi, by wypuścić ich na świat.$B', 0),
(2804, 'plPL', 'Arygos pierwszy zauważył dziwne emanacje. Monolityczna świątynia w południowej części Ahn\'Qiraj promieniowała przyćmioną magią, niepodobną do niczego, co wyczuwali u Qiraji. Choć próbowali ze wszystkich sił, nikt nie zdołał przeniknąć w głąb świątyni i odnaleźć źródła tej energii. Tylko coś o niezmierzonej mocy mogło tak doskonale się osłonić. Być może... coś, co kieruje owadami. Coś, co kieruje nawet Qiraji.', 0),
(2805, 'plPL', 'Smoki wiedziały, że muszą działać szybko, bo inaczej świat spotka kolejna wielka katastrofa. Po starannym namyśle uznano, że najlepiej będzie zatrzymać armie roju u ich źródła lub w jego pobliżu.', 0),
(2806, 'plPL', 'Miała powstać wielka bariera, czerpiąca z esencji zarówno nocnych elfów, jak i smoczych stad. Magiczna bariera, która zamknie silithidy i ich władców w murach Ahn\'Qiraj i zapobiegnie kolejnym najazdom. Samo Ahn\'Qiraj miało stać się więzieniem.', 0),
(2822, 'plPL', 'Nie rozumiesz ani słowa z tej księgi. Nie wiesz nawet, w jakim języku została napisana!', 0),
(2838, 'plPL', 'Do wszystkich zainteresowanych,\n\nJakże uwielbiam te nasze gierki. \n\nSkoro czytasz ten list, mogę tylko przypuszczać, że jakimś cudem lub dzięki boskiej interwencji udało ci się mnie pokonać. Niedorzeczne, wiem, ale w dziejach tego świata zdarzały się dziwniejsze rzeczy.\n', 0),
(2839, 'plPL', 'Jak wszystko w życiu, ta żałosna historia ma swoją wspaniałą, srebrną podszewkę z tragedii, chaosu i zła. Owszem, zginąłem z twojej ręki, ale stało się to tak powoli i nieporadnie, że zdążyłem napisać ten list JUŻ PO TYM, jak zniszczyłem twoją jedyną nadzieję na ocalenie tego świata. Zmiażdżony proszek z czerwonego kryształu to wszystko, co zostało z twojego odłamka berła.\n\n', 0),
(2840, 'plPL', 'Ciesz się uzbrojeniem nemezis i Burzogniewnego, które znajdziesz w moim skarbcu. I uwierz mi: wielką przyjemność sprawia mi świadomość, że zrobiłem to, czego nie zdołał mój ojciec...\n\n\nZ wyrazami szacunku\n\nLord Victor Nefarius\n„Nefarian”\n', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(8321, 'plPL', 'Treść na stronach tej księgi zdaje się bezustannie zmieniać. Masz wrażenie, jakby myśli wysączały ci się z umysłu, a księga je pochłaniała.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
