(6539, 7, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki inwokatora.', ''),
(6539, 8, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki inwokatora.', ''),
(6539, 9, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki obrońcy.', ''),
(6539, 10, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki obrońcy.', ''),
(6539, 11, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki obrońcy.', ''),
(6539, 12, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki obrońcy.', ''),
(6539, 13, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki zdobywcy.', ''),
(6539, 14, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki inwokatora.', ''),
(6539, 15, 'plPL', '$GZgubiłem:Zgubiłam; sygnet ścieżki obrońcy.', ''),
(6539, 16, 'plPL', 'Jestem $ggotów:gotowa;, Anachronosie. Przekaż mi, proszę, Berło Ruchomych Piasków.', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(2137, 'plPL', 'Torto, moja miłości! Nareszcie wróciłem.', '', 0),
(2138, 'plPL', 'Masz pojęcie, jak długo tu czekam? I gdzie obiad? Tyle czasu i nic z tego nie mam?', '', 0),
(2139, 'plPL', 'Najdroższa Torto, tak długo mnie nie było. Wreszcie znów jesteśmy razem. Nareszcie nasza miłość może rozkwitnąć na nowo.', '', 0),
(2140, 'plPL', 'Dość tego gadania. Umieram z głodu! A teraz wsadź tę swoją zakurzoną skorupę do oceanu i przynieś mamusi coś na ząb.', '', 0),
(2141, 'plPL', 'Tak, Torto. Czego tylko zapragnie twoje serce...', '', 0),
(2145, 'plPL', 'I spróbuj się tym razem nie zgubić...', '', 0),
(2221, 'plPL', 'Daleko jeszcze?', '', 0),
(2222, 'plPL', 'Chce mi się pić.', '', 0),
(2223, 'plPL', 'Już jesteśmy?', '', 0),
(2224, 'plPL', 'Ciągle wchodzi mi piasek między palce.', '', 0),
(2225, 'plPL', 'Ile jeszcze zostało?', '', 0),
(2226, 'plPL', 'Szkoda, że nie możesz mnie po prostu podnieść i ponieść.', '', 0),
(2227, 'plPL', 'Znasz ten dowcip o ogrze, goblinie i lordzie otchłani?', '', 0),
(2228, 'plPL', 'Torta pewnie strasznie się martwi.', '', 0),
(3661, 'plPL', '', 'Posiedź chwilkę, a ja ci to przygotuję!', 0),
(3662, 'plPL', 'Widziałeś ostatnio coś dziwnego na pustyni?', 'Widziałeś ostatnio coś dziwnego na pustyni?', 0),
(3792, 'plPL', 'Życie tu, na pustyni, jest ciężkie! Kiedy tak stoję na dworze w tym upale, strasznie chce mi się pić.', '', 0),
(3793, 'plPL', 'Tak! Chcę więcej tego wspaniałego eliksiru Noggenfoggera!', 'Tak! Chcę więcej tego wspaniałego eliksiru Noggenfoggera!', 0),
(4414, 'plPL', '', 'Użyj tego kostura rozkazów na Razie, gdy będziesz w pobliżu kłusowników Cienistego Jedwabiu, a sprawi, że pożałują dnia, w którym postanowili kłusować na tych ziemiach.', 0),
(4423, 'plPL', 'Jeśli krawiectwo to twoja działka, Vizzklick na pewno ma to, czego potrzebujesz. Rozejrzyj się, $n, i daj mi znać, jeśli zechcesz coś kupić!', '', 0),
(4424, 'plPL', 'Chcę obejrzeć twoje towary.', 'Chcę obejrzeć twoje towary.', 0),
(4425, 'plPL', 'Zbieraj manatki, $n! Właśnie dostałem wiadomość od Nilith Lokrav z Płonącego Wąwozu, że Podziemny Targ rozkręcił interes w samym sercu Kotła. Znajdź Nilith Lokrav w Płonącym Wąwozie i dowiedz się szczegółów!', '', 0),
(4512, 'plPL', 'Duch unosi się nad swoim martwym ciałem. Jego widmowe oczy przeszywają cię na wskroś, gdy spogląda gdzieś w dal...', '', 0),
(4520, 'plPL', 'No, skoro już pytasz, to tak, wczoraj po południu widziałem coś, co wydało mi się trochę dziwne!$B$BBiegłem obok starych trollowych ruin na południowy wschód stąd; no, właściwie nie biegłem, raczej podskakiwałem... Piasek jest taki gorący!$B$BW każdym razie podskakiwałem obok tych ruin, kiedy zauważyłem, że ktoś rozbił tam obóz. Jak dla mnie to dziwne miejsce na obóz... Powęszyłbym trochę dłużej, ale przegonił mnie jeden z tych wielkich, zwariowanych sępów.', '', 0),
(4548, 'plPL', 'Teraz ostrożnie to wymieszam – ups! ...No, trochę się rozlało, ale gotowe!', '', 0),
(4825, 'plPL', 'Niewielu mnie szuka... Co mogę dla ciebie zrobić?', '', 0),
(4935, 'plPL', 'Ja... nie bardzo wiem, jak się tu znalazłem...$B$BChyba pamiętam jakąś podróż... tratwę...$B$B', '', 0),
(4937, 'plPL', 'Zapłać, to powiem...$B$BO, hej, to ty, $n! Nieważne...', '', 0),
(4938, 'plPL', 'Czy moje imię brzmi dla ciebie znajomo? Może znaliśmy się dawno temu...$B$BChyba nazwano mnie na cześć kogoś ważnego...', '', 0),
(4939, 'plPL', 'Cześć! Cieszę się, że $gwróciłeś:wróciłaś;, $n. Powiedz, $gwykonałeś:wykonałaś; już pierwsze zadanie, które ci dałem? Jeśli tak, to może mam dla ciebie drugie...', '', 0),
(4940, 'plPL', 'Kiedy błąkałem się po kraterze po tym, jak się tu rozbiłem, przypomniałem sobie coś, co kiedyś mi powiedziano... „Idź w górę, w górę, na szczyt przed tobą” – powiedział głos w mojej głowie.$B$BPosłuchałem go i właśnie tak tu trafiłem, $n!', '', 0),
(4941, 'plPL', 'Dawno temu, w czasie moich podróży, spotkałem człowieka, który powiedział mi: „Opanuj używanie i możesz mieć to”.$B$BJak myślisz, co to znaczy? Wtedy nie wiedziałem i nadal właściwie nie wiem...', '', 0),
(4942, 'plPL', 'To sekret dla wszystkich... nawet dla mnie!$B$BCieszę się, że mnie $gznalazłeś:znalazłaś; – dobrze, że nie chowam się w krzakach ani pod kamieniem, prawda?', '', 0),
(5983, 'plPL', 'Ach, gość! Pewnie $gposzukiwacz:poszukiwaczka; przygód, turyści rzadko się tu zapuszczają. Weź krzesło i coś do picia, rozgość się. Słuchaj, wyglądasz, jakbyś $gmiał:miała; trochę mięcha na kościach. Nie myślisz o tym, żeby stanąć do walk w klatce?', 'Ach, gość! Pewnie $gposzukiwacz:poszukiwaczka; przygód, turyści rzadko się tu zapuszczają. Weź krzesło i coś do picia, rozgość się. Słuchaj, wyglądasz, jakbyś $gmiał:miała; trochę mięcha na kościach. Nie myślisz o tym, żeby stanąć do walk w klatce?', 0),
(6153, 'plPL', '', 'Chodź za mną, proszę.', 0),
(6154, 'plPL', '', 'Nie odkryłam jeszcze, co to takiego, ale z tymi gorącymi źródłami jest coś dziwnego...', 0),
(6155, 'plPL', '', '%s wrzuca miecz do płytkiej sadzawki.', 0),
(6156, 'plPL', '', 'Zauważyłam, że kiedy wrzucę coś do tej wody, a potem to wyciągnę, jest niesamowicie ulepszone.', 0),
(6157, 'plPL', '', 'Cokolwiek to jest, działa całkiem nieźle!', 0),
(6158, 'plPL', '', 'I jestem zdecydowana dowiedzieć się więcej... Więc jeśli znów będziesz potrzebować mojej pomocy, wiesz, gdzie mnie szukać.', 0),
(6231, 'plPL', '', '%s nerwowo się rozgląda.', 0),
(6232, 'plPL', '', 'Na pewno nikt cię tu nie śledził? Nagle mam bardzo złe przeczucie...', 0),
(6233, 'plPL', '', 'Miej się na baczności!', 0),
(6301, 'plPL', '', '%s podskakuje ze strachu!', 0),
(6306, 'plPL', '', '%s podskakuje ze strachu!', 0),
(6307, 'plPL', '', 'Aaaaa!!! Co to za stwór?!', 0),
(6308, 'plPL', '', 'To Umi cię przysłała, prawda?! Mówiła, żebym się spodziewała niespodzianki, ale nigdy bym nie pomyślała, że chodzi jej o coś takiego!', 0),
(6524, 'plPL', 'Ta robota zdecydowanie nie jest warta szesnastu i pół tysiąca rocznie.', '', 0),
(7307, 'plPL', '', 'Witaj! Co cię sprowadza do Zimozdroju? Te zimne, rozległe ziemie mogą się wydawać ponure, ale to miejsce kryje wiele tajemnic...', 0),
(7861, 'plPL', 'Pracuję nad sposobem przesyłania ropy pod ziemią między dużymi miastami, ale wszyscy mi mówią, że to pomysł wyssany z rury.', '', 0),
(9036, 'plPL', '', 'Potrzebujesz zaopatrzenia?', 0),
(9847, 'plPL', 'Nie mogę, Vaelastrazie! Na pewno da się coś zrobić, żeby cię uleczyć!', 'Nie mogę, Vaelastrazie! Na pewno da się coś zrobić, żeby cię uleczyć!', 0),
(9861, 'plPL', 'Ja... zawiodłem, $n. Władca Czar... Władca Czarnej Góry jest zbyt potężny. Pochłonął moją energię z... z łatwością. Przemieniam się... Ja... zabij mnie... musisz... musisz mnie zabić.', '', 0),
(9886, 'plPL', 'Za późno, przyjaciele! Splugawienie Nefariusa już mną zawładnęło... Nie mogę... nad sobą zapanować.\n', '', 0),
(9887, 'plPL', 'Błagam was, śmiertelnicy – UCIEKAJCIE! Uciekajcie, zanim całkiem stracę panowanie nad sobą! Czarny ogień szaleje w moim sercu! MUSZĘ go... uwolnić!', '', 0),
(9888, 'plPL', 'PŁOMIEŃ! ŚMIERĆ! ZNISZCZENIE! Kulcie się, śmiertelnicy, przed gniewem władcy... NIE – MUSZĘ z tym walczyć! Alexstrazo, pomóż mi, MUSZĘ z tym walczyć!', '', 0),
(9905, 'plPL', 'To naprawdę proste. Pozwól, że streszczę...\n', '', 0),
(9906, 'plPL', 'Proszę bardzo.', 'Proszę bardzo.', 0),
(9964, 'plPL', 'Wybacz mi, $n! Twoja śmierć tylko dopełnia mojej porażki!', '', 0),
(9965, 'plPL', 'Nienawiść Nefariusa uczyniła mnie silniejszym niż kiedykolwiek! Trzeba było uciekać, póki mogliście, śmiertelnicy! Furia Czarnej Skały płynie w moich żyłach!\n', '', 0),
(9996, 'plPL', 'Dzięki technologii odzyskanej przez dzielne gnomy, które zapuściły się do Gnomoregan, udało mi się skonstruować mój największy wynalazek: transporter materii! Teraz potrzebuję już tylko wprawnego gnomiego inżyniera, który zbuduje potężny nadajnik zestrojony z transporterem.', '', 0),
(9997, 'plPL', 'Muszę zbudować nadajnik do tego cudownego urządzenia!', 'Muszę zbudować nadajnik do tego cudownego urządzenia!', 0),
(9998, 'plPL', 'Kiedy już zbudujesz urządzenie, wystarczy je uruchomić, a w mgnieniu oka przeniesiesz się do uroczego Gadżetonu! Niemal każdy, kto użył urządzenia, pojawił się tu na platformie, wyglądając dokładnie tak samo jak na początku!\nZgłaszano pewne problemy z podróżnymi zastępowanymi przez ich złe wersje z alternatywnego wszechświata, ale jestem pewien, że wkrótce to rozwiążemy...', '', 0),
(9999, 'plPL', 'Jeśli wymyślisz, jak ulepszyć urządzenie, daj mi znać!', '', 0),
(10010, 'plPL', 'Wyświadczę ostatnią przysługę. Modlę się, by wystarczyła...', '', 0),
(10011, 'plPL', 'Vaelastrazie, nie!!!', 'Vaelastrazie, nie!!!', 0),
(10651, 'plPL', 'Spójrz za siebie. Rój się budzi, a ziemia wokół nas drży i się trzęsie.$B$BNadszedł czas, bym spełnił obietnicę złożoną tysiąc lat temu. Piaski znów się poruszają, bo Qiraji szykują się do wojny.', '', 0),
(10658, 'plPL', 'Straszny i kosztowny błąd popełniliście. To jeszcze nie mój czas, śmiertelnicy.', '', 0),
(10679, 'plPL', 'Baristolth, $gzgubiłem:zgubiłam; odznakę i potrzebuję nowej.', 'Baristolth, $gzgubiłem:zgubiłam; odznakę i potrzebuję nowej.', 0),
(10680, 'plPL', 'To my musimy zadać pierwszy cios. Nie możemy dopuścić do powtórzenia błędów przeszłości...', '', 0),
(10853, 'plPL', '%s wierci się niespokojnie.', '', 0),
(10854, 'plPL', 'Gdy nadejdzie właściwy czas, moja pani. Wszystko stanie się jasne, gdy nadejdzie właściwy czas. Mistrz już teraz się budzi. Spójrz w niebo, bo Miot Nozdormu powrócił.', '', 0),
(10902, 'plPL', 'Alexstrazo, daj mi siłę, bym odparł naszych wrogów!', '', 0),
(10907, 'plPL', 'Nie zapominaj o ofiarach poniesionych tego dnia, nocny elfie. Wszyscy wiele wycierpieliśmy z rąk tych bestii.', '', 0),
(10914, 'plPL', 'Tak, Fandralu, zapamiętaj te słowa: nie pozwól, by żal kierował twoją wiarą. Te myśli, które w sobie nosisz... w mroczne miejsca zmierzasz, nocny elfie. Rozgrzeszenia nie da się osiągnąć przez zemstę na manowcach.', '', 0),
(11086, 'plPL', '', 'Na dnie oceanu jest bardzo spokojnie.', 0),
(11087, 'plPL', '', 'Jak cudownie znów cię widzieć, $n! Nie wiem, jak ci dziękować za dostarczenie tego listu mojemu drogiemu gnomikowi.$B$BChcesz posłuchać piosenki? Dzięki niej podróż po wzburzonych morzach będzie o wiele łatwiejsza!', 0),
(11088, 'plPL', 'Byłoby cudownie! Dziękuję, Meridith.', 'Byłoby cudownie! Dziękuję, Meridith.', 0),
(11352, 'plPL', 'Nawet gdyby jakimś cudem udało ci się nas uwolnić bez pokonania C\'Thuna, skupilibyśmy wszystkie nasze moce, by odesłać tę bestię z powrotem do piekła, z którego przybyła – ZA WSZELKĄ CENĘ.', '', 0),
(11391, 'plPL', 'Nasza wolność nic by nie znaczyła, gdyby C\'Thun przeżył. Jesteś $gprawdziwym czempionem:prawdziwą czempionką; z proroctwa.', '', 0),
(11604, 'plPL', 'Gdzie jest Nestor Gromoróg?', 'Gdzie jest Nestor Gromoróg?', 0),
(11605, 'plPL', 'Z powodów, których nie potrafię pojąć, Nestor Gromoróg przebywa teraz na Pełzającej Bliźnie w Kraterze Un\'Goro.', 'Z powodów, których nie potrafię pojąć, Nestor Gromoróg przebywa teraz na Pełzającej Bliźnie w Kraterze Un\'Goro.', 0),
(11876, 'plPL', 'Jestem w 100% $gpewien:pewna;, że chcę zgłębiać tajniki goblińskiej inżynierii.', 'Jestem w 100% $gpewien:pewna;, że chcę zgłębiać tajniki goblińskiej inżynierii.', 0),
(11878, 'plPL', 'Jestem w 100% $gpewien:pewna;, że chcę zgłębiać tajniki gnomiej inżynierii.', 'Jestem w 100% $gpewien:pewna;, że chcę zgłębiać tajniki gnomiej inżynierii.', 0),
(11889, 'plPL', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa smoczołuskiego.', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa smoczołuskiego.', 0),
(11890, 'plPL', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa żywiołów.', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa żywiołów.', 0),
(11891, 'plPL', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa plemiennego.', 'Jestem absolutnie $gpewien:pewna;, że chcę się nauczyć garbarstwa plemiennego.', 0),
(12346, 'plPL', 'Co mogę dla ciebie zrobić? Nie, czekaj! Co ty możesz zrobić dla mnie?', '', 0),
(15509, 'plPL', 'Witaj w Tawernie Czasu!', '', 0),
(15510, 'plPL', 'Daj odpocząć zmęczonym nogom, mamy przecież cały czas świata...', '', 0),
(15511, 'plPL', 'Podać ci coś do picia? Obiecuję, że leżakowało jak nic innego!', '', 0),
(15784, 'plPL', 'Potrzebuję paczki bomb zapalających.', 'Potrzebuję paczki bomb zapalających.', 0),
(15785, 'plPL', 'Oto kolejne ładunki zapalające, $n. Uważaj z nimi – użyte niewłaściwie mogą poważnie zaburzyć bieg czasu.', '', 0),
(16086, 'plPL', 'Myślę, że zdołam wam dwojgu wszystko wyjaśnić, jeśli poświęcicie mi chwilę.', '', 0),
(16087, 'plPL', 'To zaklęcie powinno wymazać z ich pamięci nas i to, co się przed chwilą wydarzyło. Będą teraz pamiętać tylko to, jak wyglądałaby rzeczywistość bez próby ingerencji w czas. Dobra robota. Thrall wyruszy na spotkanie swojego przeznaczenia, a Taretha...', '', 0),
(16088, 'plPL', 'Jej losu niestety nie da się uniknąć.', '', 0),
(16450, 'plPL', 'Jesteśmy tu, żeby chronić interesy Gadżetonu w Un\'Goro, i to nie twoja sprawa.', '', 0),
(16458, 'plPL', 'Musisz użyć bomb zapalających przy beczkach w barakach internowania w Twierdzy Durnhold. Gdy odpalisz pięć bomb i dywersja będzie gotowa, znajdź Thralla w więzieniu w piwnicach Durnholdu i go uwolnij. Idź za nim i dopilnuj, żeby nie zginął!$B$BGdy będziesz $ggotów:gotowa;, Brazen zaniesie cię do Durnholdu.', '', 0),
(17541, 'plPL', '', 'Fascynujące. Co to takiego, Andormu?', 0),
(17542, 'plPL', 'Coś bardzo, bardzo niepokojącego. Zaczynamy ich widywać coraz więcej na ścieżkach czasu.', '', 0),
(17543, 'plPL', '', 'Hmm, czy majstrują przy ścieżkach czasu?', 0),
(17544, 'plPL', 'Nozari, nie mówię o chciwym czarodzieju, który chce poprawić swoją pozycję w życiu drobną zmianą w przeszłości.', '', 0),
(17545, 'plPL', 'Te istoty nie podsuwają sobie zwycięskich numerów w wichrogrodzkiej loterii, moja droga.', '', 0),
(17546, 'plPL', '', 'Nie znoszę, kiedy mówisz do mnie tym tonem. Jestem ci równa pod każdym względem, bracie. Pamiętaj o tym następnym razem, gdy utkniesz w wirze czasu i będziesz wołać o pomoc.', 0),
(17547, 'plPL', 'Przepraszam, Nozari. Ostatnio jestem trochę „podenerwowany”. Te stworzenia próbują zmienić ścieżki czasu.', '', 0),
(17548, 'plPL', 'Pamiętasz chyba, kiedy ostatnio do tego doszło? Miejmy nadzieję, że mistrz nie będzie musiał się w to mieszać.', '', 0),
(17549, 'plPL', '', 'Idziemy?', 0),
(17550, 'plPL', 'Absolutnie nie. Nie wolno nam się narażać. Pod nieobecność mistrza tylko my dbamy o to, by strumień pozostał nienaruszony. Lada chwila przybędą inni. Bohaterowie i poszukiwacze przygód z Azeroth...', '', 0),
(17564, 'plPL', 'Witaj. Co tu robię, to opowieść na inny czas. Uch, to był kiepski żart.$B$BMój brat i ja utknęliśmy tu, między naszym czasem a teraźniejszością. Nie śmiemy odejść, bo moglibyśmy wywołać paradoks czasowy. Cierpliwie czekamy, aż smoki przywrócą nas na właściwą linię czasu.$B$BJak długo już to trwa, pytasz? Właściwie nie wiem. Zapytaj mojego brata.$B$BMasz ochotę na ser?', '', 0),
(17566, 'plPL', 'Ser, co? Czy to może... ser długo dojrzewający?', 'Ser, co? Czy to może... ser długo dojrzewający?', 0),
(17572, 'plPL', 'Nie, nie przesłyszało ci się. Naprawdę mam głos młodej orczycy. Ale słuchaj no, $gchłopcze:dziewczyno;, podróże w czasie dziwnie działają na ciało.$B$BA tak przy okazji: 250 lat.', '', 0),
(17574, 'plPL', 'Potrzebuję składników i trucizn, paniusiu.', 'Potrzebuję składników i trucizn, paniusiu.', 0),
(17579, 'plPL', 'Tak, tkwię tu, odkąd pamiętam.$B$BW poprzednim życiu byłem płatnerzem. Może mogę ci coś naprawić?', '', 0),
(17580, 'plPL', 'Potrzebuję naprawy.', 'Potrzebuję naprawy.', 0),
(17740, 'plPL', 'Strzeż się, $gśmiertelniku:śmiertelniczko;, za tą salą czyhają niebezpieczeństwa, o jakich nie słyszano w twoim świecie. Stąpaj ostrożnie...', '', 0),
(17741, 'plPL', 'Dobrze znów cię widzieć, $n. Czy mam cię zabrać do leża mistrza?', '', 0),
(17742, 'plPL', 'Proszę, zabierz mnie do leża mistrza.', 'Proszę, zabierz mnie do leża mistrza.', 0),
(17814, 'plPL', 'Stój! Nie idź dalej, $gśmiertelniku:śmiertelniczko;. Nie jesteś $gprzygotowany:przygotowana; na starcie z siłami Nieskończonego Stada. Chodź, pozwól, że ci pomogę.', '', 0),
(17878, 'plPL', 'Witaj, $gposzukiwaczu:poszukiwaczko; przygód. Posłuchaj moich ostrzeżeń, zanim wyruszysz na Czarne Mokradła.', '', 0),
(17879, 'plPL', 'Sa\'at, $gzgubiłem:zgubiłam; chronolatarnię i potrzebuję nowej!', 'Sa\'at, $gzgubiłem:zgubiłam; chronolatarnię i potrzebuję nowej!', 0),
(17880, 'plPL', 'Ach, witaj z powrotem, $gbohaterze:bohaterko;. $GWróciłeś:Wróciłaś;, by znów chronić Strażnika? Nie zapomnij zabrać ze sobą chronolatarni!', '', 0),
(17881, 'plPL', 'Potrzebuję chronolatarni, Sa\'at.', 'Potrzebuję chronolatarni, Sa\'at.', 0),
(17882, 'plPL', 'Witaj, $n. Idź ostrożnie...', '', 0),
(18192, 'plPL', 'Siema. Jestem Vixton Szczypogwizd, oficjalny sprzedawca areny Ligi Walk Parochlebców. Jeśli masz odpowiednią reputację, to ja mam towar, na widok którego ślinka ci pocieknie.', '', 0),
(18663, 'plPL', '', 'Bitwa o Górę Hyjal to jedno z najpilniej strzeżonych wydarzeń tej linii czasu. Gdyby jakiś intruz zmienił jej wynik, skutki objęłyby wszystkie późniejsze chwile w dziejach.$B$BJako pierwsza małżonka Aspektu jestem o wiele bardziej zestrojona z biegiem czasu niż inne brązowe smoki. Niedawno wyczułam drobną zmarszczkę w czasie, która bierze początek w wydarzeniach wokół Bitwy o Górę Hyjal. Ktoś lub coś próbuje zmienić tę linię czasu i trzeba go powstrzymać.', 0),
(18973, 'plPL', '', 'Cieszę się, że $gpostanowiłeś:postanowiłaś; wesprzeć naszą sprawę. W nagrodę nasycę obrączkę resztkami Studni Wieczności, które mi $gprzyniosłeś:przyniosłaś;.$B$BOferuję ci cztery różne ścieżki, by uwolnić ich moc. Wybieraj mądrze, $n. Piaski czasu łatwo płyną w jedną stronę, ale nie w drugą.', 0),
(21813, 'plPL', 'Chyba gdzieś $gzapodziałem:zapodziałam; obrączkę.', 'Chyba gdzieś $gzapodziałem:zapodziałam; obrączkę.', 0),
(27525, 'plPL', 'Nie zwracaj na mnie uwagi. Jestem tylko starym człowiekiem, który czeka na starego... przyjaciela.', '', 0),
(36143, 'plPL', 'Chcę zapomnieć specjalizację gnomiej inżynierii!', 'Chcę zapomnieć specjalizację gnomiej inżynierii!', 0),
(36144, 'plPL', 'Czy na pewno chcesz zapomnieć specjalizację gnomiej inżynierii i utracić wszystkie związane z nią schematy?', 'Czy na pewno chcesz zapomnieć specjalizację gnomiej inżynierii i utracić wszystkie związane z nią schematy?', 0),
(36145, 'plPL', 'Czy na pewno chcesz zapomnieć specjalizację goblińskiej inżynierii i utracić wszystkie związane z nią schematy?', 'Czy na pewno chcesz zapomnieć specjalizację goblińskiej inżynierii i utracić wszystkie związane z nią schematy?', 0),
(36146, 'plPL', 'Chcę zapomnieć specjalizację goblińskiej inżynierii!', 'Chcę zapomnieć specjalizację goblińskiej inżynierii!', 0),
(38807, 'plPL', 'Chcę obejrzeć twoje towary.', 'Chcę obejrzeć twoje towary.', 0),
(39180, 'plPL', 'W imieniu znamienitego i wciąż neutralnego Kartelu Parochlebców życzę ci miłego pobytu.$B$BPamiętaj, w Gadżetonie każdy jest mile widziany! Każdy oprócz piratów.', '', 0),
(64242, 'plPL', '', 'Już jesteśmy?', 0);
